#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void max_reduce_dim1_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int Outer, int Reduce, int Inner)
{
  // Process the fastest-varying (inner) dimension in vector-of-4 chunks to
  // increase bytes moved per memory transaction while keeping the access
  // pattern coalesced (threads still map to consecutive inner indices, just
  // 4 at a time). A grid-stride loop covers the vectorized part; leftover
  // inner elements (Inner % 4) are handled by a second grid-stride loop.
  int inner_vec = Inner / 4;
  int inner_rem = Inner - inner_vec * 4;
  int64_t total_vec = (int64_t)Outer * (int64_t)inner_vec;
  int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)blockDim.x * gridDim.x;
  for (int64_t i = idx; i < total_vec; i += stride) {
    int outer = (int)(i / inner_vec);
    int inner_group = (int)(i % inner_vec);
    int inner = inner_group * 4;
    const T* __restrict__ base = X + (int64_t)outer * Reduce * Inner + inner;
    float4 maxval = *reinterpret_cast<const float4*>(base);
    #pragma unroll 4
    for (int r = 1; r < Reduce; ++r) {
      float4 v = *reinterpret_cast<const float4*>(base + (int64_t)r * Inner);
      maxval.x = v.x > maxval.x ? v.x : maxval.x;
      maxval.y = v.y > maxval.y ? v.y : maxval.y;
      maxval.z = v.z > maxval.z ? v.z : maxval.z;
      maxval.w = v.w > maxval.w ? v.w : maxval.w;
    }
    *reinterpret_cast<float4*>(Y + (int64_t)outer * Inner + inner) = maxval;
  }
  if (inner_rem > 0) {
    int64_t total_rem = (int64_t)Outer * (int64_t)inner_rem;
    for (int64_t i = idx; i < total_rem; i += stride) {
      int outer = (int)(i / inner_rem);
      int rem_idx = (int)(i % inner_rem);
      int inner = inner_vec * 4 + rem_idx;
      const T* __restrict__ base = X + (int64_t)outer * Reduce * Inner + inner;
      T maxval = base[0];
      #pragma unroll 4
      for (int r = 1; r < Reduce; ++r) {
        T v = base[(int64_t)r * Inner];
        maxval = v > maxval ? v : maxval;
      }
      Y[(int64_t)outer * Inner + inner] = maxval;
    }
  }
}
template <typename T>
__global__ void max_reduce_dim1_kernel_scalar(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int Outer, int Reduce, int Inner)
{
  int64_t total = (int64_t)Outer * (int64_t)Inner;
  int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)blockDim.x * gridDim.x;
  for (int64_t i = idx; i < total; i += stride) {
    int outer = (int)(i / Inner);
    int inner = (int)(i % Inner);
    const T* __restrict__ base = X + (int64_t)outer * Reduce * Inner + inner;
    // Use eight independent accumulators fed from interleaved reduce-dim
    // elements to further increase memory-level parallelism and hide
    // global memory latency (Inner is odd here, so float2/float4 vector
    // loads are not applicable across the strided reduce dimension).
    T maxval0 = base[0];
    T maxval1 = (Reduce > 1) ? base[(int64_t)Inner] : base[0];
    T maxval2 = (Reduce > 2) ? base[(int64_t)2 * Inner] : base[0];
    T maxval3 = (Reduce > 3) ? base[(int64_t)3 * Inner] : base[0];
    T maxval4 = (Reduce > 4) ? base[(int64_t)4 * Inner] : base[0];
    T maxval5 = (Reduce > 5) ? base[(int64_t)5 * Inner] : base[0];
    T maxval6 = (Reduce > 6) ? base[(int64_t)6 * Inner] : base[0];
    T maxval7 = (Reduce > 7) ? base[(int64_t)7 * Inner] : base[0];
    int r = 8;
    #pragma unroll 4
    for (; r + 7 < Reduce; r += 8) {
      T v0 = base[(int64_t)r * Inner];
      T v1 = base[(int64_t)(r + 1) * Inner];
      T v2 = base[(int64_t)(r + 2) * Inner];
      T v3 = base[(int64_t)(r + 3) * Inner];
      T v4 = base[(int64_t)(r + 4) * Inner];
      T v5 = base[(int64_t)(r + 5) * Inner];
      T v6 = base[(int64_t)(r + 6) * Inner];
      T v7 = base[(int64_t)(r + 7) * Inner];
      maxval0 = v0 > maxval0 ? v0 : maxval0;
      maxval1 = v1 > maxval1 ? v1 : maxval1;
      maxval2 = v2 > maxval2 ? v2 : maxval2;
      maxval3 = v3 > maxval3 ? v3 : maxval3;
      maxval4 = v4 > maxval4 ? v4 : maxval4;
      maxval5 = v5 > maxval5 ? v5 : maxval5;
      maxval6 = v6 > maxval6 ? v6 : maxval6;
      maxval7 = v7 > maxval7 ? v7 : maxval7;
    }
    for (; r < Reduce; ++r) {
      T v0 = base[(int64_t)r * Inner];
      maxval0 = v0 > maxval0 ? v0 : maxval0;
    }
    T maxval_a = maxval0 > maxval1 ? maxval0 : maxval1;
    T maxval_b = maxval2 > maxval3 ? maxval2 : maxval3;
    T maxval_c = maxval4 > maxval5 ? maxval4 : maxval5;
    T maxval_d = maxval6 > maxval7 ? maxval6 : maxval7;
    T maxval_ab = maxval_a > maxval_b ? maxval_a : maxval_b;
    T maxval_cd = maxval_c > maxval_d ? maxval_c : maxval_d;
    T maxval = maxval_ab > maxval_cd ? maxval_ab : maxval_cd;
    Y[(int64_t)outer * Inner + inner] = maxval;
