  // (or has an odd tail of size 1). Vectorizes 2 elements at a time to
  // still increase bytes-per-transaction versus the pure scalar path.
  int inner_vec = Inner / 2;
  int inner_rem = Inner - inner_vec * 2;
  int64_t total_vec = (int64_t)Outer * (int64_t)inner_vec;
  int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)blockDim.x * gridDim.x;
  for (int64_t i = idx; i < total_vec; i += stride) {
    int outer = (int)(i / inner_vec);
    int inner_group = (int)(i % inner_vec);
    int inner = inner_group * 2;
    const T* __restrict__ base = X + (int64_t)outer * Reduce * Inner + inner;
    float2 maxval = *reinterpret_cast<const float2*>(base);
    #pragma unroll 4
    for (int r = 1; r < Reduce; ++r) {
      float2 v = *reinterpret_cast<const float2*>(base + (int64_t)r * Inner);
      maxval.x = v.x > maxval.x ? v.x : maxval.x;
      maxval.y = v.y > maxval.y ? v.y : maxval.y;
    }
    *reinterpret_cast<float2*>(Y + (int64_t)outer * Inner + inner) = maxval;
  }
  if (inner_rem > 0) {
    int64_t total_rem = (int64_t)Outer * (int64_t)inner_rem;
    for (int64_t i = idx; i < total_rem; i += stride) {
      int outer = (int)(i / inner_rem);
      int rem_idx = (int)(i % inner_rem);
      int inner = inner_vec * 2 + rem_idx;
      const T* __restrict__ base = X + (int64_t)outer * Reduce * Inner + inner;
      T maxval = base[0];
      #pragma unroll 4
      for (int r = 1; r < Reduce; ++r) {
        T v = base[(int64_t)r * Inner];
        maxval = v > maxval ? v : maxval;
      }
      Y[(int64_t)outer * Inner + inner] = maxval;
    }
  }
}
torch::Tensor max_reduce_dim_forward(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == torch::kFloat32, "only float32 is supported");
  int64_t ndim = x.dim();
  if (dim < 0) dim += ndim;
  TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");
  auto x_c = x.contiguous();
  int64_t outer = 1;
  for (int64_t i = 0; i < dim; ++i) outer *= x_c.size(i);
  int64_t reduce = x_c.size(dim);
  int64_t inner = 1;
  for (int64_t i = dim + 1; i < ndim; ++i) inner *= x_c.size(i);
  std::vector<int64_t> out_sizes;
  out_sizes.reserve(ndim - 1);
  for (int64_t i = 0; i < ndim; ++i) {
    if (i == dim) continue;
    out_sizes.push_back(x_c.size(i));
  }
  auto y = torch::empty(out_sizes, x_c.options());
  const int Threads = 256;
  int64_t inner_vec4 = inner / 4;
  bool can_vectorize4 = (inner % 4 == 0) && (inner_vec4 > 0) &&
      (reinterpret_cast<uintptr_t>(x_c.data_ptr<float>()) % 16 == 0) &&
      (reinterpret_cast<uintptr_t>(y.data_ptr<float>()) % 16 == 0);
  int64_t inner_vec2 = inner / 2;
  bool can_vectorize2 = (!can_vectorize4) && (inner % 2 == 0) && (inner_vec2 > 0) &&
      (reinterpret_cast<uintptr_t>(x_c.data_ptr<float>()) % 8 == 0) &&
      (reinterpret_cast<uintptr_t>(y.data_ptr<float>()) % 8 == 0);
  int mode = can_vectorize4 ? 2 : (can_vectorize2 ? 1 : 0);
  int64_t total_work = (mode == 2) ? outer * inner_vec4 : (mode == 1) ? outer * inner_vec2 : outer * inner;
  // Size the grid to avoid a large partial tail wave: launch enough blocks
  // to keep the GPU busy (a fixed multiple of the SM count), and let each
  // thread process multiple elements via the grid-stride loop above.
  int device = 0;
  cudaGetDevice(&device);
  int sm_count = 1;
  cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, device);
  int blocks_per_sm = 1;
  if (mode == 2) {
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks_per_sm, max_reduce_dim1_kernel<float>, Threads, 0);
  } else if (mode == 1) {
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks_per_sm, max_reduce_dim1_kernel_vec2<float>, Threads, 0);
  } else {
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks_per_sm, max_reduce_dim1_kernel_scalar<float>, Threads, 0);
  }
  if (blocks_per_sm < 1) blocks_per_sm = 1;
  int64_t needed_blocks = (total_work + Threads - 1) / Threads;
  int64_t blocks_per_wave = (int64_t)sm_count * (int64_t)blocks_per_sm;
  if (blocks_per_wave < 1) blocks_per_wave = 1;
  int64_t waves = (needed_blocks + blocks_per_wave - 1) / blocks_per_wave;
  if (waves < 1) waves = 1;
  int64_t grid_blocks = waves * blocks_per_wave;
  if (grid_blocks < 1) grid_blocks = 1;
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream();
  if (mode == 2) {
    max_reduce_dim1_kernel<float><<<(unsigned int)grid_blocks, Threads, 0, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        (int)outer, (int)reduce, (int)inner
    );
  } else if (mode == 1) {
    max_reduce_dim1_kernel_vec2<float><<<(unsigned int)grid_blocks, Threads, 0, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        (int)outer, (int)reduce, (int)inner
    );
  } else {
    max_reduce_dim1_kernel_scalar<float><<<(unsigned int)grid_blocks, Threads, 0, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        (int)outer, (int)reduce, (int)inner
    );
  }
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "max_reduce_dim1_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
