template <typename T>
__global__ void max_reduce_dim1_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int Outer, int Reduce, int Inner)
{
  // Each thread handles one (outer, inner) pair, reducing over "Reduce" dim.
  int outer = blockIdx.y;
  int inner = blockIdx.x * blockDim.x + threadIdx.x;

